import pyomo.environ as pyo

DATA = {
    # products and equipment
    "products": ["I", "II", "III"],
    "A_equip": ["A1", "A2"],
    "B_equip": ["B1", "B2", "B3"],

    # Table 1-18: A-equipment unit processing times (min/unit)
    "time_A": {
        ("A1", "I"): 5, ("A1", "II"): 10,
        ("A2", "I"): 7, ("A2", "II"): 9, ("A2", "III"): 12,
    },
    # Table 1-18: B-equipment unit processing times (min/unit)
    "time_B": {
        ("B1", "I"): 6, ("B1", "II"): 8,
        ("B2", "I"): 4, ("B2", "III"): 11,
        ("B3", "I"): 7,
    },

    # Table 1-18: Equipment available time
    "avail_A": {"A1": 6000, "A2": 10000},
    "avail_B": {"B1": 4000, "B2": 7000, "B3": 4000},

    # Table 1-18: Equipment cost at full load (CNY)
    "cost_A": {"A1": 300, "A2": 321},
    "cost_B": {"B1": 250, "B2": 783, "B3": 200},

    # Table 1-18: raw material cost (CNY/unit)
    "raw": {"I": 0.25, "II": 0.35, "III": 0.50},

    # Table 1-18: unit price (CNY/unit)
    "price": {"I": 1.25, "II": 2.00, "III": 2.80},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.A = pyo.Set(initialize=d["A_equip"])
    model.B = pyo.Set(initialize=d["B_equip"])

    # Valid (equipment, product) pairs, based on eligibility rules
    model.A_pairs = pyo.Set(
        dimen=2,
        initialize=[(a, p) for a in d["A_equip"] for p in d["products"]
                    if (a, p) in d["time_A"]],
    )
    model.B_pairs = pyo.Set(
        dimen=2,
        initialize=[(b, p) for b in d["B_equip"] for p in d["products"]
                    if (b, p) in d["time_B"]],
    )

    # Decision: units of each product to produce
    model.x = pyo.Var(model.P, within=pyo.NonNegativeReals)

    # Objective: maximize revenue - raw material cost - equipment (time-proportional) cost
    def revenue(m):
        return sum(d["price"][p] * m.x[p] for p in m.P)

    def raw_cost(m):
        return sum(d["raw"][p] * m.x[p] for p in m.P)

    def equip_cost(m):
        cost = 0
        for a in m.A:
            rate = d["cost_A"][a] / d["avail_A"][a]
            for p in m.P:
                if (a, p) in d["time_A"]:
                    cost += rate * d["time_A"][(a, p)] * m.x[p]
        for b in m.B:
            rate = d["cost_B"][b] / d["avail_B"][b]
            for p in m.P:
                if (b, p) in d["time_B"]:
                    cost += rate * d["time_B"][(b, p)] * m.x[p]
        return cost

    model.obj = pyo.Objective(
        expr=revenue(model) - raw_cost(model) - equip_cost(model),
        sense=pyo.maximize,
    )

    # A-equipment capacity constraints
    def rule_A(m, a):
        return sum(d["time_A"][(a, p)] * m.x[p]
                   for p in m.P if (a, p) in d["time_A"]) <= d["avail_A"][a]
    model.cap_A = pyo.Constraint(model.A, rule=rule_A)

    # B-equipment capacity constraints
    def rule_B(m, b):
        return sum(d["time_B"][(b, p)] * m.x[p]
                   for p in m.P if (b, p) in d["time_B"]) <= d["avail_B"][b]
    model.cap_B = pyo.Constraint(model.B, rule=rule_B)

    return model


